"use client";

import { useEffect, useMemo, useState } from "react";

import KpiCard from "@/components/kpis/KpiCard";

import {
  calculateKPIs,
  calculateMonthlyRevenue,
  calculateRevenueByChannel,
  calculateRevenueByCity,
  formatCurrency,
} from "@/lib/analytics";

import { 
  loadSales, 
  loadProperties 
} from "@/lib/data";

import type {
  Property,
  RevenueByChannel,
  RevenueByCity,
  Sale,
} from "@/lib/types";

import MonthlyRevenueChart from "@/components/charts/MonthlyRevenueChart";
import RevenueByCityChart from "@/components/charts/RevenueByCityChart";
import RevenueByChannelChart from "@/components/charts/RevenueByChannelChart";

import DashboardFilters from "@/components/filters/DashboardFilters";

export default function Home() {
  const [
    revenueByCity,
    setRevenueByCity,
  ] = useState<RevenueByCity[]>([]);
  const [
    revenueByChannel,
    setRevenueByChannel,
  ] = useState<RevenueByChannel[]>([]);
    const [sales, setSales] =
    useState<Sale[]>([]);

  const [properties, setProperties] =
    useState<Property[]>([]);

  const [selectedCity, setSelectedCity] =
    useState("all");

  const [selectedYear, setSelectedYear] =
    useState("all");

  const [loading, setLoading] =
    useState(true);

  const [error, setError] =
    useState<string | null>(null);


  useEffect(() => {
    async function fetchData() {
      try {
        const [
          salesData,
          propertiesData,
        ] = await Promise.all([
          loadSales(),
          loadProperties(),
        ]);

        setSales(salesData);
        setProperties(propertiesData);

      } catch (err) {
        console.error(err);

        if (err instanceof Error) {
          setError(err.message);
        } else {
          setError(
            "Failed to load dashboard data."
          );
        }

      } finally {
        setLoading(false);
      }
    }

    fetchData();
  }, []);

  const cities = useMemo(() => {
    return Array.from(
      new Set(
        properties.map(
          (property) => property.city
        )
      )
    ).sort();
  }, [properties]);

  const years = useMemo(() => {
    return Array.from(
      new Set(
        sales.map(
          (sale) =>
            Number(
              sale.saleDate.slice(0, 4)
            )
        )
      )
    ).sort((a, b) => a - b);
  }, [sales]);

  const propertyMap = useMemo(() => {
    return new Map(
      properties.map((property) => [
        property.propertyId,
        property,
      ])
    );
  }, [properties]);


  if (loading) {
    return (
      <main className="p-8">
        Loading dashboard...
      </main>
    );
  }


  if (error) {
    return (
      <main className="p-8">
        <p className="text-red-600">
          {error}
        </p>
      </main>
    );
  }


  if (!kpis) {
    return null;
  }


  return (
    <main className="min-h-screen bg-gray-50 px-6 py-8">
      <div className="mx-auto max-w-7xl">

        <header>
          <p className="text-sm font-medium text-gray-500">
            Real Estate Sales Analytics
          </p>

          <h1 className="mt-1 text-3xl font-bold tracking-tight text-gray-900">
            Desempeño Comercial
          </h1>

          <p className="mt-2 text-sm text-gray-500">
            Análisis de ingresos, eficiencia comercial
            y desempeño de ventas.
          </p>
        </header>


        <section className="mt-8 grid gap-4 sm:grid-cols-2 lg:grid-cols-4">

          <KpiCard
            title="Ingreso Total"
            value={formatCurrency(
              kpis.totalRevenue
            )}
            subtitle="Ingresos acumulados"
          />

          <KpiCard
            title="Cantidad de Ventas"
            value={
              kpis.totalSales.toLocaleString()
            }
            subtitle="Operaciones realizadas"
          />

          <KpiCard
            title="Ticket Promedio"
            value={formatCurrency(
              kpis.averageTicket
            )}
            subtitle="Ingreso promedio por venta"
          />

          <KpiCard
            title="Comisión Total"
            value={formatCurrency(
              kpis.totalCommission
            )}
            subtitle="Comisiones generadas"
          />

        </section>

        <section className="mt-6">
          <MonthlyRevenueChart
            data={monthlyRevenue}
          />
        </section>

        <section className="mt-6 grid gap-6 lg:grid-cols-2">
          <RevenueByCityChart
            data={revenueByCity}
          />

          <RevenueByChannelChart
            data={revenueByChannel}
          />

        </section>

      </div>
    </main>
  );
}